// The printer panel's own parts: the card pinned above the thread, the cards
// the agent draws inside it, and the row of things to tap.
//
// Everything here renders host state. A tap either sends a typed printer
// action, which C++ carries out, or sends the chip's own words as the
// person's message -- never both, and never a change made on this side.

import { ChangeEvent, memo, useRef, useState } from 'react';
import type {
  AttachmentSource,
  NetworkPrinterInfo,
  PrinterBlock,
  PrinterBrowse,
  PrinterCardInfo,
  PrinterChip,
  PrinterFact,
  PrinterSessionPayload,
} from '../bridge/protocol';

const EM_DASH = '—';

function factClass(fact: PrinterFact): string {
  if (!fact.value) return 'printer-fact-value printer-fact-empty';
  return `printer-fact-value printer-fact-${fact.provenance}`;
}

function factSuffix(fact: PrinterFact): string {
  if (!fact.value) return '';
  if (fact.provenance === 'assumed') return ' · assumed';
  if (fact.provenance === 'changed') return ' · changed';
  return '';
}

function FactRow({ label, fact }: { label: string; fact: PrinterFact }) {
  return (
    <div className="printer-fact">
      <span className="printer-fact-label">{label}</span>
      <span className={factClass(fact)}>
        {fact.swatch && <span className="printer-swatch" style={{ background: fact.swatch }} aria-hidden="true" />}
        {fact.value || EM_DASH}
        {factSuffix(fact)}
      </span>
    </div>
  );
}

// The four facts a printer is, in the order the panel always states them.
export const PrinterPinnedCard = memo(function PrinterPinnedCard({ session }: { session: PrinterSessionPayload }) {
  return (
    <section className="printer-pinned" aria-label={session.caption}>
      <p className="printer-pinned-caption">{session.caption}</p>
      <FactRow label="Printer" fact={session.facts.printer} />
      <FactRow label="Nozzle" fact={session.facts.nozzle} />
      <FactRow label="Plate" fact={session.facts.plate} />
      <FactRow label="Filament" fact={session.facts.filament} />
    </section>
  );
});

// The camera the panel shows wherever a photo is offered. Inline, like the
// composer's send arrow, because the icon set carries no camera yet.
export function CameraGlyph({ className }: { className: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
      <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z" />
      <circle cx="12" cy="13" r="4" />
    </svg>
  );
}

export interface PrinterBlockProps {
  block: PrinterBlock;
  onAction: (
    action: 'network_pick' | 'candidate_pick' | 'add' | 'add_anyway' | 'reject' | 'browse' | 'manual_setup',
    id: string,
  ) => void;
}

// Brand on its own small line, model bold beneath it: never one joined
// string, which is how "Bambulab Bambu Lab A1 mini" happened.
function CardName({ printer }: { printer: PrinterCardInfo }) {
  return (
    <span className="printer-card-name">
      <span className="printer-card-vendor">{printer.vendor}</span>
      <b>{printer.model}</b>
      {printer.subline && <small>{printer.subline}</small>}
    </span>
  );
}

function CardPicture({ printer }: { printer: PrinterCardInfo }) {
  return printer.picture ? (
    <img className="printer-card-picture" src={printer.picture} alt="" />
  ) : (
    <span className="printer-card-picture printer-card-picture-empty" aria-hidden="true" />
  );
}

// One card the agent drew, in the thread, under the message that drew it.
export const PrinterBlockView = memo(function PrinterBlockView({ block, onAction }: PrinterBlockProps) {
  if (block.kind === 'tip')
    return (
      <div className="printer-tip">
        <CameraGlyph className="printer-tip-icon" />
        <span>
          <b>Tip:</b> a photo is the fastest way. Use <b>Photo</b> below, or drop a picture of the printer, its nameplate or the box
          into this panel.
        </span>
      </div>
    );

  if (block.kind === 'network') {
    const found = (block.printers ?? []) as NetworkPrinterInfo[];
    return (
      <div className="printer-found">
        <p className="printer-found-caption">FOUND ON YOUR NETWORK</p>
        {found.map((printer) => (
          <div className="printer-row" key={printer.deviceId}>
            <span className={printer.online ? 'printer-dot printer-dot-online' : 'printer-dot'} aria-hidden="true" />
            <span className="printer-row-name">
              {printer.name}
              <small>{printer.serial}</small>
            </span>
            <button type="button" className="printer-quiet-button" onClick={() => onAction('network_pick', printer.deviceId)}>
              Use this
            </button>
          </div>
        ))}
      </div>
    );
  }

  // Not a printer this app ships a profile for: the panel itself draws the
  // way out, so it is never lost in how the agent happened to phrase it.
  if (block.kind === 'unsupported')
    return (
      <div className="printer-exit">
        <button type="button" className="printer-exit-row" onClick={() => onAction('browse', '')}>
          <span>Browse the full list</span>
          <span aria-hidden="true">›</span>
        </button>
        <button type="button" className="printer-exit-row" onClick={() => onAction('manual_setup', '')}>
          <span>
            Set it up myself
            <small>for a printer you built, or one that isn't listed</small>
          </span>
          <span aria-hidden="true">›</span>
        </button>
      </div>
    );

  // The network find a live proposal card names went quiet between "Use
  // this" and Add (WP11): the card above is untouched, this is the one red
  // line with its fix, as a chip either way -- never silently added or
  // refused.
  if (block.kind === 'offline')
    return (
      <div className="printer-failure">
        <span>It stopped answering. Add it anyway, or check that it’s on.</span>
        <div className="printer-failure-actions">
          <button type="button" className="printer-quiet-button printer-failure-action" onClick={() => onAction('add_anyway', '')}>
            Add it anyway
          </button>
          <button type="button" className="printer-quiet-button" onClick={() => onAction('add', '')}>
            Check again
          </button>
        </div>
      </div>
    );

  const printers = (block.printers ?? []) as PrinterCardInfo[];

  // Superseded by a newer answer, or the person's own "Not this one": no
  // button, no picture, one quiet line each. Only one live card at a time.
  // "Not this one" is only true for a card that actually offered it -- the
  // single confident propose ('add'). A multi-candidate ask only ever
  // offered "This one" per card; the person answered past it rather than
  // rejecting any one of them, so claiming they did would be putting words
  // in their mouth.
  if (block.live === false)
    return (
      <div className="printer-cards-collapsed">
        {printers.map((printer) => (
          <div className="printer-card-collapsed" key={printer.catalogId}>
            {/* The model name already carries the vendor's ("Bambu Lab X1
                Carbon"), so this stays one clean line instead of repeating
                it from the vendor field too. */}
            Not this one · {printer.model}
          </div>
        ))}
      </div>
    );

  // One printer, confidently: the card owns "Add this printer", bottom
  // right, with "Not this one" a quiet line beneath -- never a docked Add
  // at the panel's foot. Two or three: each carries its own "This one" and
  // nothing here is red, because nothing is settled yet.
  const single = printers.length === 1 && printers[0].action === 'add';

  if (single) {
    const printer = printers[0];
    return (
      <div className="printer-cards-wrap">
        <div className="printer-card printer-card-propose">
          <div className="printer-card-top">
            <CardPicture printer={printer} />
            <CardName printer={printer} />
          </div>
          <button type="button" className="printer-card-add" onClick={() => onAction('add', printer.catalogId)}>
            Add this printer
          </button>
        </div>
        <button type="button" className="printer-reject-line" onClick={() => onAction('reject', printer.catalogId)}>
          Not this one
        </button>
      </div>
    );
  }

  // Two or three, still a question: each keeps its own row and button, and
  // nothing here is red, because nothing is settled yet.
  return (
    <div className="printer-cards printer-cards-compact">
      {printers.map((printer) => (
        <div className="printer-card" key={printer.catalogId}>
          <CardPicture printer={printer} />
          <CardName printer={printer} />
          <button type="button" className="printer-quiet-button" onClick={() => onAction('candidate_pick', printer.catalogId)}>
            This one
          </button>
        </div>
      ))}
    </div>
  );
});

export interface ChipRowProps {
  chips: PrinterChip[];
  hint: string;
  disabled: boolean;
  onSay: (text: string) => void;
  // "Photo of the label" opens the same picker "Photo" does, rather than
  // sending its label as a message.
  onAttachFiles: (files: File[], source: AttachmentSource) => void;
}

// Specific actions, never a bare Yes or No, with the composer always beneath.
export const PrinterChipRow = memo(function PrinterChipRow({ chips, hint, disabled, onSay, onAttachFiles }: ChipRowProps) {
  const fileInput = useRef<HTMLInputElement>(null);
  if (chips.length === 0) return null;

  const handlePickerChange = (event: ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(event.target.files ?? []);
    event.target.value = '';
    if (files.length > 0) onAttachFiles(files, 'picker');
  };

  return (
    <div className="printer-chips">
      {chips.map((chip) => (
        <button
          key={chip.id}
          type="button"
          className={`printer-chip printer-chip-${chip.style}`}
          disabled={disabled}
          onClick={() => (chip.opensPhotoPicker ? fileInput.current?.click() : onSay(chip.say))}
        >
          {chip.label}
        </button>
      ))}
      {hint && <span className="printer-chip-hint">{hint}</span>}
      <input
        ref={fileInput}
        type="file"
        multiple
        className="attach-input"
        aria-hidden="true"
        tabIndex={-1}
        style={{ display: 'none' }}
        onChange={handlePickerChange}
      />
    </div>
  );
});

export interface PrinterBrowseProps {
  browse: PrinterBrowse;
  onBack: () => void;
  onOpenVendor: (vendorId: string) => void;
  onPick: (catalogId: string) => void;
  onManualSetup: () => void;
}

// Brands, then one vendor's models, inside the panel: replaces the thread
// while it is open, the way a layer over it never quite reads as "still in
// this conversation."
export const PrinterBrowseView = memo(function PrinterBrowseView({
  browse,
  onBack,
  onOpenVendor,
  onPick,
  onManualSetup,
}: PrinterBrowseProps) {
  const [filter, setFilter] = useState('');
  if (!browse) return null;

  if (browse.level === 'vendors') {
    const query = filter.trim().toLowerCase();
    const rows = query ? browse.vendors.filter((vendor) => vendor.name.toLowerCase().includes(query)) : browse.vendors;
    return (
      <div className="printer-browse">
        <button type="button" className="printer-browse-back" onClick={onBack}>
          ‹ Back to chat
        </button>
        <input
          type="text"
          className="printer-browse-filter"
          placeholder="Filter brands"
          value={filter}
          onChange={(event) => setFilter(event.target.value)}
        />
        <div className="printer-browse-rows">
          {rows.map((vendor) => (
            <button key={vendor.id} type="button" className="printer-browse-row" onClick={() => onOpenVendor(vendor.id)}>
              <span>{vendor.name}</span>
              <small>{vendor.count}</small>
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="printer-browse">
      <button type="button" className="printer-browse-back" onClick={onBack}>
        ‹ Brands
      </button>
      <p className="printer-browse-caption">
        {browse.vendorName} · {browse.models.length}
      </p>
      <div className="printer-browse-rows">
        {browse.models.map((model) => (
          <button
            key={model.catalogId}
            type="button"
            className="printer-browse-row printer-browse-model"
            onClick={() => onPick(model.catalogId)}
          >
            {model.picture ? (
              <img className="printer-browse-picture" src={model.picture} alt="" />
            ) : (
              <span className="printer-browse-picture printer-browse-picture-empty" aria-hidden="true" />
            )}
            <span>
              <b>{model.model}</b>
              <small>{model.subline}</small>
            </span>
          </button>
        ))}
        <button type="button" className="printer-browse-row printer-browse-manual" onClick={onManualSetup}>
          <span>
            Set it up myself
            <small>my printer isn't listed</small>
          </span>
        </button>
      </div>
    </div>
  );
});

// What the printer panel states and what a tap on it does. The panel renders
// host state and sends typed actions; nothing here decides a printer fact on
// its own, so these tests pin the reading and the sending, not a model.

import { describe, expect, it, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import type { PrinterBlock, PrinterChip, PrinterSessionPayload } from '../bridge/protocol';
import { PrinterBlockView, PrinterChipRow, PrinterPinnedCard } from './PrinterPanel';

function session(overrides: Partial<PrinterSessionPayload> = {}): PrinterSessionPayload {
  return {
    mode: 'add',
    caption: 'NEW PRINTER',
    facts: {
      printer: { value: '', provenance: 'settled' },
      nozzle: { value: '', provenance: 'settled' },
      plate: { value: '', provenance: 'settled' },
      filament: { value: '', provenance: 'settled' },
    },
    blocks: [],
    chips: [],
    chipHint: '',
    placeholder: 'e.g. "bambu a1 mini" or "not sure, the small one"',
    browse: null,
    ...overrides,
  };
}

describe('the pinned card', () => {
  it('states the four facts in order, with an em dash for what nobody has said', () => {
    render(<PrinterPinnedCard session={session()} />);

    expect(screen.getByText('NEW PRINTER')).toBeInTheDocument();
    const labels = screen.getAllByText(/^(Printer|Nozzle|Plate|Filament)$/).map((node) => node.textContent);
    expect(labels).toEqual(['Printer', 'Nozzle', 'Plate', 'Filament']);
    expect(screen.getAllByText('—')).toHaveLength(4);
  });

  it('marks an assumed fact as assumed and a changed one as changed', () => {
    render(
      <PrinterPinnedCard
        session={session({
          caption: 'PRINTER',
          mode: 'change',
          facts: {
            printer: { value: 'Bambu Lab A1 Combo', provenance: 'settled' },
            nozzle: { value: '0.6 mm', provenance: 'changed' },
            plate: { value: 'Textured PEI', provenance: 'assumed' },
            filament: { value: 'AMS · 4 slots', provenance: 'settled', swatch: '#5f7d4f' },
          },
        })}
      />,
    );

    expect(screen.getByText(/Textured PEI · assumed/)).toBeInTheDocument();
    const changed = screen.getByText(/0\.6 mm · changed/);
    expect(changed).toHaveClass('printer-fact-changed');
    // A settled fact says nothing about where it came from.
    expect(screen.getByText(/Bambu Lab A1 Combo/)).not.toHaveTextContent('assumed');
  });
});

describe('the cards the agent draws', () => {
  const printers: PrinterBlock = {
    id: 'b1',
    seq: 1,
    afterMessageId: 'm1',
    kind: 'printers',
    live: true,
    printers: [
      {
        catalogId: 'BBL/Bambu Lab A1 mini',
        deviceId: '',
        vendor: 'Bambu Lab',
        model: 'A1 mini',
        subline: '180 × 180 × 180 mm',
        picture: '',
        action: 'add',
      },
    ],
  };

  it('gives one printer the full card, brand and model on their own lines', () => {
    render(<PrinterBlockView block={printers} onAction={vi.fn()} />);

    expect(screen.getByText('Bambu Lab')).toBeInTheDocument();
    expect(screen.getByText('A1 mini')).toBeInTheDocument();
    expect(screen.getByText('180 × 180 × 180 mm')).toBeInTheDocument();
  });

  it('owns "Add this printer" on the card and offers "Not this one" beside it', async () => {
    const onAction = vi.fn();
    render(<PrinterBlockView block={printers} onAction={onAction} />);

    await userEvent.click(screen.getByRole('button', { name: 'Add this printer' }));
    expect(onAction).toHaveBeenCalledWith('add', 'BBL/Bambu Lab A1 mini');

    await userEvent.click(screen.getByRole('button', { name: 'Not this one' }));
    expect(onAction).toHaveBeenCalledWith('reject', 'BBL/Bambu Lab A1 mini');
  });

  it('asks which of two printers it is, on the cards themselves, with no Add anywhere', async () => {
    const onAction = vi.fn();
    render(
      <PrinterBlockView
        block={{
          ...printers,
          printers: [
            { catalogId: 'Creality/Ender-3 V2', deviceId: '', vendor: 'Creality', model: 'Ender-3 V2', subline: '', picture: '', action: 'choose' },
            { catalogId: 'Creality/Ender-3 S1', deviceId: '', vendor: 'Creality', model: 'Ender-3 S1', subline: '', picture: '', action: 'choose' },
          ],
        }}
        onAction={onAction}
      />,
    );

    const buttons = screen.getAllByRole('button', { name: 'This one' });
    expect(buttons).toHaveLength(2);
    expect(screen.queryByRole('button', { name: 'Add this printer' })).toBeNull();
    await userEvent.click(buttons[1]);
    expect(onAction).toHaveBeenCalledWith('candidate_pick', 'Creality/Ender-3 S1');
  });

  it('collapses a superseded or rejected card to one grey line, no button', () => {
    render(<PrinterBlockView block={{ ...printers, live: false }} onAction={vi.fn()} />);

    expect(screen.getByText('Not this one · A1 mini')).toBeInTheDocument();
    expect(screen.queryByRole('button')).toBeNull();
  });

  // A multi-candidate ask never offered a per-card "Not this one" -- only
  // "This one" -- so a later answer superseding it collapses to the bare
  // name, not a rejection nobody made.
  it('collapses a superseded multi-candidate ask without claiming a rejection', () => {
    render(
      <PrinterBlockView
        block={{
          ...printers,
          live: false,
          printers: [
            { catalogId: 'Creality/Ender-3 V2', deviceId: '', vendor: 'Creality', model: 'Ender-3 V2', subline: '', picture: '', action: 'choose' },
            { catalogId: 'Creality/Ender-3 S1', deviceId: '', vendor: 'Creality', model: 'Ender-3 S1', subline: '', picture: '', action: 'choose' },
          ],
        }}
        onAction={vi.fn()}
      />,
    );

    expect(screen.getByText('Ender-3 V2')).toBeInTheDocument();
    expect(screen.getByText('Ender-3 S1')).toBeInTheDocument();
    expect(screen.queryByText(/Not this one/)).toBeNull();
  });

  it('lists what is on the network, with its serial and a way to use it', async () => {
    const onAction = vi.fn();
    render(
      <PrinterBlockView
        block={{
          id: 'b2',
          seq: 2,
          afterMessageId: 'm1',
          kind: 'network',
          printers: [{ deviceId: '01P00A3B', name: 'Bambu Lab A1 mini', serial: '01P00A3B', online: true }],
        }}
        onAction={onAction}
      />,
    );

    expect(screen.getByText('FOUND ON YOUR NETWORK')).toBeInTheDocument();
    expect(screen.getByText('01P00A3B')).toBeInTheDocument();
    await userEvent.click(screen.getByRole('button', { name: 'Use this' }));
    expect(onAction).toHaveBeenCalledWith('network_pick', '01P00A3B');
  });

  it('says how a photo gets in, in words', () => {
    render(<PrinterBlockView block={{ id: 'b3', seq: 3, afterMessageId: 'm1', kind: 'tip' }} onAction={vi.fn()} />);
    expect(screen.getByText(/a photo is the fastest way/)).toBeInTheDocument();
  });

  it('draws its own way out when the printer is not on the list', async () => {
    const onAction = vi.fn();
    render(
      <PrinterBlockView
        block={{ id: 'b4', seq: 4, afterMessageId: 'm1', kind: 'unsupported', reason: 'not_listed' }}
        onAction={onAction}
      />,
    );

    expect(screen.getByText('Browse the full list')).toBeInTheDocument();
    expect(screen.getByText('Set it up myself')).toBeInTheDocument();
    await userEvent.click(screen.getByText('Browse the full list'));
    expect(onAction).toHaveBeenCalledWith('browse', '');
    await userEvent.click(screen.getByText('Set it up myself'));
    expect(onAction).toHaveBeenCalledWith('manual_setup', '');
  });

  // WP11: a network find that went quiet between "Use this" and Add draws
  // one red line with its fix, as a chip either way.
  it('offers to add anyway or check again when the network printer went quiet', async () => {
    const onAction = vi.fn();
    render(<PrinterBlockView block={{ id: 'b5', seq: 5, afterMessageId: 'm1', kind: 'offline' }} onAction={onAction} />);

    expect(screen.getByText('It stopped answering. Add it anyway, or check that it’s on.')).toBeInTheDocument();
    await userEvent.click(screen.getByText('Add it anyway'));
    expect(onAction).toHaveBeenCalledWith('add_anyway', '');
    await userEvent.click(screen.getByText('Check again'));
    expect(onAction).toHaveBeenCalledWith('add', '');
  });
});

describe('the chips', () => {
  const chips: PrinterChip[] = [
    { id: 's1', label: 'Use 0.3 mm layers', style: 'suggested', say: 'Use 0.3 mm layers', opensPhotoPicker: false },
  ];

  it('sends a chip as the person\'s own words', async () => {
    const onSay = vi.fn();
    render(<PrinterChipRow chips={chips} hint="or just type" disabled={false} onSay={onSay} onAttachFiles={vi.fn()} />);

    await userEvent.click(screen.getByRole('button', { name: 'Use 0.3 mm layers' }));
    expect(onSay).toHaveBeenCalledWith('Use 0.3 mm layers');
    expect(screen.getByText('or just type')).toBeInTheDocument();
  });

  it('offers nothing while the agent is working', async () => {
    const onSay = vi.fn();
    render(<PrinterChipRow chips={chips} hint="" disabled onSay={onSay} onAttachFiles={vi.fn()} />);
    await userEvent.click(screen.getByRole('button', { name: 'Use 0.3 mm layers' }));
    expect(onSay).not.toHaveBeenCalled();
  });

  it('"Photo of the label" opens the picker instead of sending its label', async () => {
    const onSay = vi.fn();
    const photoChips: PrinterChip[] = [
      { id: 's1', label: 'Photo of the label', style: 'suggested', say: 'Photo of the label', opensPhotoPicker: true },
    ];
    const { container } = render(
      <PrinterChipRow chips={photoChips} hint="" disabled={false} onSay={onSay} onAttachFiles={vi.fn()} />,
    );
    const clickSpy = vi.spyOn(HTMLInputElement.prototype, 'click');

    await userEvent.click(screen.getByRole('button', { name: 'Photo of the label' }));

    expect(onSay).not.toHaveBeenCalled();
    expect(clickSpy).toHaveBeenCalled();
    expect(container.querySelector('input[type="file"]')).not.toBeNull();
  });
});

