    m_persistence.set_draft({});
    send_envelope(Protocol::kMessageAdded, json{{"message", message_json(message)}}.dump(), envelope_id);

    cancel_conversation_title();
    if (agent_busy()) {
        // The page disables sending while a reply streams; if a message
